import random
from datetime import datetime, timedelta
from pathlib import Path

from datasets_shared.schema.models import EmailTextParameterSet
from faker import Faker
from pydantic import BaseModel, TypeAdapter


class EmailTextParameterSetListPayload(BaseModel):
    """The collection of parameter sets generated by the LLM."""

    parameters: list[EmailTextParameterSet]


email_text_parameterset_list_adapter = TypeAdapter(list[EmailTextParameterSet])


def generate_parameters(count: int, locales: list[str]) -> list[EmailTextParameterSet]:
    """
    Generate and save parameters with versioning using Faker library.

    Args:
        count: Number of parameter sets to generate
        oracle_fn: Oracle function to call (unused - kept for compatibility)
        locales: List of locales to use for name generation. If None, uses default.
                 Currencies are automatically matched to locales.

    Returns:
        List of generated parameters with unique client names, dates, and payment amounts
    """

    # Map locales to their corresponding currencies
    locale_currency_map = {"en_US": "$", "en_GB": "£", "ja_JP": "¥", "ko_KR": "₩"}

    # Extract currencies that match the provided locales
    currencies = [
        locale_currency_map[locale] for locale in locales if locale in locale_currency_map
    ]

    # Initialize Faker with specified locales for diverse names
    fake = Faker(locales)

    # Track uniqueness
    used_names: set[str] = set()
    used_dates: set[str] = set()
    used_amounts: set[str] = set()

    # Date range: from 1 year ago to today
    start_date = datetime.now() - timedelta(days=365)
    end_date = datetime.now()

    params = []

    for i in range(count):
        # Generate unique client name
        max_attempts = 100
        client_name = None
        for _ in range(max_attempts):
            # Mix different name patterns for diversity
            name_type = random.choice(["full_name", "first_last", "with_middle"])
            if name_type == "full_name":
                name = fake.name()
            elif name_type == "first_last":
                name = f"{fake.first_name()} {fake.last_name()}"
            else:  # with_middle
                name = f"{fake.first_name()} {fake.first_name()[0]}. {fake.last_name()}"

            if name not in used_names:
                client_name = name
                used_names.add(name)
                break

        if client_name is None:
            raise ValueError(f"Could not generate unique client name after {max_attempts} attempts")

        # Generate unique date
        date_str = None
        for _ in range(max_attempts):
            random_date = fake.date_between(start_date=start_date, end_date=end_date)
            date_str = random_date.strftime("%Y-%m-%d")
            if date_str not in used_dates:
                used_dates.add(date_str)
                break

        if date_str is None:
            raise ValueError(f"Could not generate unique date after {max_attempts} attempts")

        # Generate unique payment amount
        amount_str = None
        for _ in range(max_attempts):
            # Generate realistic payment amounts ($0.99 to $99.99)
            amount = round(random.uniform(0.99, 20.00), 2)
            # Mix different currencies for diversity
            currency = random.choice(currencies)
            amount_str = f"{currency}{amount:.2f}"
            if amount_str not in used_amounts:
                used_amounts.add(amount_str)
                break

        if amount_str is None:
            raise ValueError(
                f"Could not generate unique payment amount after {max_attempts} attempts"
            )

        # Create parameter set
        param = EmailTextParameterSet(
            client_name=client_name, date=date_str, payment_amount=amount_str
        )
        params.append(param)

    # Convert parameters to dictionaries for JSON serialization
    params_data = [param.model_dump() for param in params]

    # Publish with versioning
    metadata = {
        "count": count,
        "generated_at": str(Path(__file__).name),
        "total_parameters": len(params),
        "generator": "faker",
        "unique_names": len(used_names),
        "unique_dates": len(used_dates),
        "unique_amounts": len(used_amounts),
    }

    return params
